ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "country" TEXT, ADD COLUMN IF NOT EXISTS "city" TEXT;
ALTER TABLE "Event" ADD COLUMN IF NOT EXISTS "rejectionReason" TEXT, ADD COLUMN IF NOT EXISTS "isPrivateForBadges" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Deal" ADD COLUMN IF NOT EXISTS "leisureItemId" TEXT, ADD COLUMN IF NOT EXISTS "promotionType" TEXT, ADD COLUMN IF NOT EXISTS "promotionStatus" TEXT DEFAULT 'inactive', ADD COLUMN IF NOT EXISTS "promotionStartDate" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "promotionEndDate" TIMESTAMP(3);
DO $$ BEGIN ALTER TABLE "Deal" ADD CONSTRAINT "Deal_leisureItemId_fkey" FOREIGN KEY ("leisureItemId") REFERENCES "LeisureItem"("id") ON DELETE SET NULL ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE "Ticket" ADD COLUMN IF NOT EXISTS "refundReason" TEXT, ADD COLUMN IF NOT EXISTS "refundRequestedAt" TIMESTAMP(3);
ALTER TABLE "AccessBadge" ADD COLUMN IF NOT EXISTS "eventLabel" TEXT, ADD COLUMN IF NOT EXISTS "categoryLabel" TEXT, ADD COLUMN IF NOT EXISTS "createdById" TEXT;
ALTER TABLE "AccessBadge" ALTER COLUMN "eventId" DROP NOT NULL;
ALTER TABLE "AccessBadge" ALTER COLUMN "categoryId" DROP NOT NULL;
UPDATE "AccessBadge" b SET "createdById" = e."organizerId" FROM "Event" e WHERE b."eventId" = e."id" AND b."createdById" IS NULL;
ALTER TABLE "AccessBadge" ALTER COLUMN "createdById" SET NOT NULL;
DO $$ BEGIN ALTER TABLE "AccessBadge" ADD CONSTRAINT "AccessBadge_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE INDEX IF NOT EXISTS "AccessBadge_createdById_idx" ON "AccessBadge"("createdById");
CREATE TABLE IF NOT EXISTS "PromotionPackConfig" ("type" TEXT NOT NULL, "price" INTEGER NOT NULL DEFAULT 0, "currency" TEXT NOT NULL DEFAULT 'FCFA', "description" TEXT NOT NULL DEFAULT '', "advantages" TEXT NOT NULL DEFAULT '[]', "durationDays" INTEGER NOT NULL DEFAULT 30, "updatedAt" TIMESTAMP(3) NOT NULL, "updatedBy" TEXT, CONSTRAINT "PromotionPackConfig_pkey" PRIMARY KEY ("type"));
CREATE TABLE IF NOT EXISTS "PromotionPurchase" ("id" TEXT NOT NULL, "eventId" TEXT NOT NULL, "organizerId" TEXT NOT NULL, "packType" TEXT NOT NULL, "pricePaid" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'FCFA', "status" TEXT NOT NULL DEFAULT 'completed', "paymentMode" TEXT NOT NULL DEFAULT 'immediate', "paymentStatus" TEXT NOT NULL DEFAULT 'pending', "paymentProvider" TEXT, "paymentSimulated" BOOLEAN NOT NULL DEFAULT false, "paymentRef" TEXT, "amountDeducted" INTEGER NOT NULL DEFAULT 0, "promotionStartDate" TIMESTAMP(3) NOT NULL, "promotionEndDate" TIMESTAMP(3) NOT NULL, "deactivatedAt" TIMESTAMP(3), "deactivatedBy" TEXT, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PromotionPurchase_pkey" PRIMARY KEY ("id"));
DO $$ BEGIN ALTER TABLE "PromotionPurchase" ADD CONSTRAINT "PromotionPurchase_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "PromotionPurchase" ADD CONSTRAINT "PromotionPurchase_organizerId_fkey" FOREIGN KEY ("organizerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "EstablishmentSubscription" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "leisureItemId" TEXT NOT NULL, "startDate" TIMESTAMP(3) NOT NULL, "endDate" TIMESTAMP(3) NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "currency" TEXT NOT NULL DEFAULT 'FCFA', "status" TEXT NOT NULL DEFAULT 'pending', "paymentMethod" TEXT, "paymentRef" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EstablishmentSubscription_pkey" PRIMARY KEY ("id"));
