CREATE TABLE IF NOT EXISTS "BadgePricingConfig" ("id" TEXT NOT NULL DEFAULT 'default', "unitCost" INTEGER NOT NULL DEFAULT 500, "currency" TEXT NOT NULL DEFAULT 'FCFA', "updatedAt" TIMESTAMP(3) NOT NULL, "updatedBy" TEXT, CONSTRAINT "BadgePricingConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "BadgeOrder" ("id" TEXT NOT NULL, "eventId" TEXT NOT NULL, "organizerId" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unitCost" INTEGER NOT NULL, "totalAmount" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'FCFA', "status" TEXT NOT NULL DEFAULT 'pending', "paymentMethod" TEXT, "paymentRef" TEXT, "paidAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "BadgeOrder_pkey" PRIMARY KEY ("id"));
