CREATE TABLE IF NOT EXISTS "DealPayment" ("id" TEXT NOT NULL, "dealId" TEXT, "userId" TEXT NOT NULL, "leisureItemId" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "currency" TEXT NOT NULL DEFAULT 'FCFA', "status" TEXT NOT NULL DEFAULT 'pending', "paymentMethod" TEXT, "paymentRef" TEXT, "dealData" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DealPayment_pkey" PRIMARY KEY ("id"));
